function bindPromoScroll(scope){
  (scope||root())?.querySelectorAll('[data-promo]').forEach(promo=>{
    if(promo.dataset.scrollBound==='1') return;
    promo.dataset.scrollBound='1';
    let down=false,startX=0,startLeft=0,moved=false;
    const onDown=e=>{
      down=true; moved=false;
      startX=e.clientX||(e.touches&&e.touches[0]?e.touches[0].clientX:0);
      startLeft=promo.scrollLeft;
      promo.classList.add('is-dragging');
    };
    const onMove=e=>{
      if(!down) return;
      const x=e.clientX||(e.touches&&e.touches[0]?e.touches[0].clientX:0);
      const dx=x-startX;
      if(Math.abs(dx)>4) moved=true;
      promo.scrollLeft=startLeft-dx;
      if(e.cancelable&&moved) e.preventDefault();
    };
    const onUp=()=>{
      down=false;
      promo.classList.remove('is-dragging');
      if(moved) promo.dataset.blockClick='1';
      setTimeout(()=>{delete promo.dataset.blockClick;},80);
    };
    promo.addEventListener('mousedown',onDown);
    window.addEventListener('mousemove',onMove);
    window.addEventListener('mouseup',onUp);
    promo.addEventListener('touchstart',onDown,{passive:true});
    promo.addEventListener('touchmove',onMove,{passive:false});
    promo.addEventListener('touchend',onUp);
    promo.addEventListener('click',e=>{
      if(promo.dataset.blockClick==='1'){e.preventDefault();e.stopPropagation();}
    },true);
  });
}
AS.bindPromoScroll=bindPromoScroll;

function snapWheel(wheel){
  const vp=wheel.querySelector('[data-wheel-viewport]');
  const list=wheel.querySelector('[data-wheel-list]');
  if(!vp||!list) return;
  const items=Array.from(list.querySelectorAll('[data-wheel-item]'));
  if(!items.length) return;
  const mid=vp.scrollTop+vp.clientHeight/2;
  let best=items[0],bestDist=Infinity;
  items.forEach(it=>{
    const c=it.offsetTop+it.offsetHeight/2;
    const d=Math.abs(c-mid);
    if(d<bestDist){bestDist=d;best=it;}
  });
  items.forEach(it=>it.classList.toggle('is-center',it===best));
  const target=best.offsetTop-(vp.clientHeight-best.offsetHeight)/2;
  if(Math.abs(vp.scrollTop-target)>1) vp.scrollTo({top:target,behavior:'smooth'});
}

function bindWheel(scope){
  (scope||root())?.querySelectorAll('[data-wheel]').forEach(wheel=>{
    if(wheel.dataset.wheelBound==='1') return;
    wheel.dataset.wheelBound='1';
    const vp=wheel.querySelector('[data-wheel-viewport]');
    if(!vp) return;
    let timer=null;
    const sync=()=>{
      const list=wheel.querySelector('[data-wheel-list]');
      const items=list?Array.from(list.querySelectorAll('[data-wheel-item]')):[];
      const mid=vp.scrollTop+vp.clientHeight/2;
      let best=null,bestDist=Infinity;
      items.forEach(it=>{
        const c=it.offsetTop+it.offsetHeight/2;
        const d=Math.abs(c-mid);
        if(d<bestDist){bestDist=d;best=it;}
        const t=Math.min(1,d/(vp.clientHeight*0.55));
        it.style.setProperty('--wheel-scale',String((1-t*0.28).toFixed(3)));
        it.style.setProperty('--wheel-opacity',String((1-t*0.72).toFixed(3)));
      });
      items.forEach(it=>it.classList.toggle('is-center',it===best));
    };
    vp.addEventListener('scroll',()=>{
      sync();
      clearTimeout(timer);
      timer=setTimeout(()=>snapWheel(wheel),90);
    },{passive:true});
    requestAnimationFrame(()=>{
      const active=wheel.querySelector('.st-wheel__item.is-active')||wheel.querySelector('[data-wheel-item]');
      if(active){
        const target=active.offsetTop-(vp.clientHeight-active.offsetHeight)/2;
        vp.scrollTop=Math.max(0,target);
      }
      sync();
    });
  });
}
AS.bindWheel=bindWheel;

function shuffleInPlace(arr){
  const a=arr.slice();
  for(let i=a.length-1;i>0;i--){
    const j=Math.floor(Math.random()*(i+1));
    const t=a[i]; a[i]=a[j]; a[j]=t;
  }
  return a;
}
AS.shuffleInPlace=shuffleInPlace;

function parseReleaseTs(raw){
  const s=String(raw||'').trim();
  if(!s) return 0;
  let m=s.match(/(\d{1,2})[./](\d{1,2})[./](\d{4})/);
  if(m) return Date.UTC(+m[3], +m[2]-1, +m[1]);
  m=s.match(/(\d{4})-(\d{1,2})-(\d{1,2})/);
  if(m) return Date.UTC(+m[1], +m[2]-1, +m[3]);
  const t=Date.parse(s);
  return isFinite(t)?t:0;
}
AS.parseReleaseTs=parseReleaseTs;

function sortByReleaseDesc(games){
  return (games||[]).slice().sort((a,b)=>{
    const db=parseReleaseTs(b&&b.release_date)-parseReleaseTs(a&&a.release_date);
    if(db) return db;
    return String((a&&a.title)||'').localeCompare(String((b&&b.title)||''),'ru');
  });
}
AS.sortByReleaseDesc=sortByReleaseDesc;

function sectionRowHtml(sec){
  if(!sec||!sec.games||!sec.games.length) return '';
  const key=sec.key||'';
  let list=sec.games;
  if(key!=='preorders' && key!=='novinki'){
    list=shuffleInPlace(sec.games);
  }
  const cards=list.slice(0,24).map(cardHtml).join('');
  return `<section class="st-section" data-sec="${esc(sec.key)}">
<div class="st-section__head"><h2 class="st-section__title">${esc(sec.title)}</h2>
<button type="button" class="st-section__more" data-section="${esc(sec.key)}">Все →</button></div>
<div class="st-row">${cards}</div></section>`;
}

